import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const y=JSON.parse('{"title":"Electronic","description":"","frontmatter":{},"headers":[],"relativePath":"demos/ELECTRONIC.md","filePath":"demos/ELECTRONIC.md"}'),l={name:"demos/ELECTRONIC.md"};function i(o,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="electronic" tabindex="-1">Electronic <a class="header-anchor" href="#electronic" aria-label="Permalink to &quot;Electronic&quot;">​</a></h1><p>The demo songs in the electronic style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#acid_articulate">Articulate</a>: <code>15_acid_articulate.yml</code></li><li><a href="#acid_glide">Glide and Shorten</a>: <code>14_acid_glide.yml</code></li><li><a href="#edm_density">Density</a>: <code>edm_density.yml</code></li><li><a href="#mainstreet_hoedown">Baroque Hoedown</a>: <code>mainstreet_hoedown.yml</code></li><li><a href="#microwave_snacks">Synthesizer Novelty Tune</a>: <code>microwave_snacks.yml</code></li><li><a href="#minimal_techno">Minimal Techno</a>: <code>minimal_techno.yml</code></li><li><a href="#mtn_king_direction">Directions</a>: <code>10_mtn_king_direction.yml</code></li><li><a href="#nomore_nomore">Eurodance</a>: <code>nomore_nomore.yml</code></li><li><a href="#ode_to_joy_ratchet">Ratchets</a>: <code>11_ode_to_joy_ratchet.yml</code></li><li><a href="#registers">Registers</a>: <code>22_registers.yml</code></li><li><a href="#sailor_arpeggiator">Arpeggiator</a>: <code>12_sailor_arpeggiator.yml</code></li><li><a href="#sandworm">Trance Builds by Density</a>: <code>sandworm.yml</code></li><li><a href="#techno_morph">Morphing</a>: <code>18_techno_morph.yml</code></li><li><a href="#the_mineral">Big Beat</a>: <code>the_mineral.yml</code></li><li><a href="#tie">Ties</a>: <code>08_tie.yml</code></li></ul><p><a id="acid_articulate"></a></p><h2 id="articulate-15-acid-articulate-yml" tabindex="-1">Articulate: <code>15_acid_articulate.yml</code> <a class="header-anchor" href="#articulate-15-acid-articulate-yml" aria-label="Permalink to &quot;Articulate: `15_acid_articulate.yml`&quot;">​</a></h2><p>An acid house line played the whole way through, whose notes lengthen from short blips into long, gliding, joined notes over each scene while its filter opens, with no gate changed. The demo sets Articulate on the scenes, on the line itself and as a generator that bounces between short and long every bar, and a register bound to CC 74 opens the filter as the notes lengthen.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/15_acid_articulate.yml" target="_blank" rel="noreferrer"><code>examples/learning/15_acid_articulate.yml</code></a> · A minor · 120 BPM · 3:00 · 9 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">CCs</th><th style="text-align:center;">registers</th><th style="text-align:center;">binding</th><th style="text-align:center;">shapes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="acid_glide"></a></p><h2 id="glide-and-shorten-14-acid-glide-yml" tabindex="-1">Glide and Shorten: <code>14_acid_glide.yml</code> <a class="header-anchor" href="#glide-and-shorten-14-acid-glide-yml" aria-label="Permalink to &quot;Glide and Shorten: `14_acid_glide.yml`&quot;">​</a></h2><p>Fluid acid techno for a synth with portamento: one sixteen-note acid line from start to finish, and Glide and Shorten rows of 5, 7 and 3 steps putting its slides and short notes somewhere new each bar, though the line itself never changes.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/14_acid_glide.yml" target="_blank" rel="noreferrer"><code>examples/learning/14_acid_glide.yml</code></a> · A minor · 128 BPM · 3:00 · 8 scenes · 4 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">feel</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="edm_density"></a></p><h2 id="density-edm-density-yml" tabindex="-1">Density: <code>edm_density.yml</code> <a class="header-anchor" href="#density-edm-density-yml" aria-label="Permalink to &quot;Density: `edm_density.yml`&quot;">​</a></h2><p>A club track at 128 beats a minute in F minor whose every intro, build, breakdown and drop comes from Density, which keeps a share of a clip&#39;s notes, the strongest places in the bar first. The same seven patterns, each written at the busiest it will ever play, run through every scene, and only the densities change: the scenes&#39; own ramps fill the intro and the builds in and strip the outro away, and four Density generators, sparse, half, rise and fall, thin the breakdown, turn the drums half time and make the arp and the lead trade places across the second drop.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/edm_density.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/edm_density.yml</code></a> · F minor · 128 BPM · 3:00 · 8 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a href="https://www.youtube.com/watch?v=68vSj5sSW3c" target="_blank" rel="noreferrer"><img src="https://img.youtube.com/vi/68vSj5sSW3c/hqdefault.jpg" alt="The Density demo, edm_density.yml, on YouTube"></a></p><p><a id="mainstreet_hoedown"></a></p><h2 id="baroque-hoedown-mainstreet-hoedown-yml" tabindex="-1">Baroque Hoedown: <code>mainstreet_hoedown.yml</code> <a class="header-anchor" href="#baroque-hoedown-mainstreet-hoedown-yml" aria-label="Permalink to &quot;Baroque Hoedown: `mainstreet_hoedown.yml`&quot;">​</a></h2><p>A piece rather than a demo: an original Baroque hoedown for a Moog, with a very slight Drift on its loudness.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/mainstreet_hoedown.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/mainstreet_hoedown.yml</code></a> · C major · 138 BPM · 2:55 · 12 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">registers</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="microwave_snacks"></a></p><h2 id="synthesizer-novelty-tune-microwave-snacks-yml" tabindex="-1">Synthesizer Novelty Tune: <code>microwave_snacks.yml</code> <a class="header-anchor" href="#synthesizer-novelty-tune-microwave-snacks-yml" aria-label="Permalink to &quot;Synthesizer Novelty Tune: `microwave_snacks.yml`&quot;">​</a></h2><p>An early-seventies novelty tune in the manner of Popcorn, with a tune of its own that bounces off a high repeated note every other sixteenth, and claves kept to 5 of every 8 steps by their track&#39;s Euclidean mask.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/microwave_snacks.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/microwave_snacks.yml</code></a> · A minor · 130 BPM · 2:57 · 8 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">progressions</th><th style="text-align:center;">euclid</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="minimal_techno"></a></p><h2 id="minimal-techno-minimal-techno-yml" tabindex="-1">Minimal Techno: <code>minimal_techno.yml</code> <a class="header-anchor" href="#minimal-techno-minimal-techno-yml" aria-label="Permalink to &quot;Minimal Techno: `minimal_techno.yml`&quot;">​</a></h2><p>A piece rather than a demo: minimal techno, meant only to sound good, about three minutes long.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/minimal_techno.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/minimal_techno.yml</code></a> · F minor · 126 BPM · 3:00 · 8 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">morphs</th><th style="text-align:center;">probability</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="mtn_king_direction"></a></p><h2 id="directions-10-mtn-king-direction-yml" tabindex="-1">Directions: <code>10_mtn_king_direction.yml</code> <a class="header-anchor" href="#directions-10-mtn-king-direction-yml" aria-label="Permalink to &quot;Directions: `10_mtn_king_direction.yml`&quot;">​</a></h2><p>The theme of In the Hall of the Mountain King played in each of the step directions, from forward and the two reverses to pendulum, random and brownian. The demo also shows that a clip&#39;s direction overrides its pattern&#39;s.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/10_mtn_king_direction.yml" target="_blank" rel="noreferrer"><code>examples/learning/10_mtn_king_direction.yml</code></a> · B minor · 138 BPM · 2:33 · 11 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">directions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="nomore_nomore"></a></p><h2 id="eurodance-nomore-nomore-yml" tabindex="-1">Eurodance: <code>nomore_nomore.yml</code> <a class="header-anchor" href="#eurodance-nomore-nomore-yml" aria-label="Permalink to &quot;Eurodance: `nomore_nomore.yml`&quot;">​</a></h2><p>An early-nineties eurodance song in the manner of What Is Love, with a melody of its own: an off- beat synth bass, a syncopated piano, a pad and sixteenth hats.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/nomore_nomore.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/nomore_nomore.yml</code></a> · D minor · 124 BPM · 2:58 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="ode_to_joy_ratchet"></a></p><h2 id="ratchets-11-ode-to-joy-ratchet-yml" tabindex="-1">Ratchets: <code>11_ode_to_joy_ratchet.yml</code> <a class="header-anchor" href="#ratchets-11-ode-to-joy-ratchet-yml" aria-label="Permalink to &quot;Ratchets: `11_ode_to_joy_ratchet.yml`&quot;">​</a></h2><p>The first line of Ode to Joy, slowed down to long notes, and then chopped up. The scenes named Ratchet use a pattern&#39;s own Ratchet, Ratchet offset and Probability rows. The scenes named AutoRatchet leave the pattern alone and do the chopping in a chain instead.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/11_ode_to_joy_ratchet.yml" target="_blank" rel="noreferrer"><code>examples/learning/11_ode_to_joy_ratchet.yml</code></a> · D major · 144 BPM · 4:00 · 18 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">probability</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="registers"></a></p><h2 id="registers-22-registers-yml" tabindex="-1">Registers: <code>22_registers.yml</code> <a class="header-anchor" href="#registers-22-registers-yml" aria-label="Permalink to &quot;Registers: `22_registers.yml`&quot;">​</a></h2><p>An acid techno riff of five notes, changed bar by bar by the four registers, AX to DX. AX, BX and CX each move a different note of the riff, in cycles of 4, 6 and 5 bars, then all three at once. Then DX fades the riff, kick and hat out together over six repeats of the last scene.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/22_registers.yml" target="_blank" rel="noreferrer"><code>examples/learning/22_registers.yml</code></a> · A minor · 132 BPM · 1:35 · 5 scenes · 3 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">registers</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="sailor_arpeggiator"></a></p><h2 id="arpeggiator-12-sailor-arpeggiator-yml" tabindex="-1">Arpeggiator: <code>12_sailor_arpeggiator.yml</code> <a class="header-anchor" href="#arpeggiator-12-sailor-arpeggiator-yml" aria-label="Permalink to &quot;Arpeggiator: `12_sailor_arpeggiator.yml`&quot;">​</a></h2><p>The verse of What Shall We Do With the Drunken Sailor, with its chords played through a different arpeggiator in every scene: step lengths, orders, octave ranges and jumps, offsets, and then combinations of them. The tune plays alongside, plainly, so you can mute it and hear only the arpeggio.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/12_sailor_arpeggiator.yml" target="_blank" rel="noreferrer"><code>examples/learning/12_sailor_arpeggiator.yml</code></a> · D dorian · 112 BPM · 3:26 · 24 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="sandworm"></a></p><h2 id="trance-builds-by-density-sandworm-yml" tabindex="-1">Trance Builds by Density: <code>sandworm.yml</code> <a class="header-anchor" href="#trance-builds-by-density-sandworm-yml" aria-label="Permalink to &quot;Trance Builds by Density: `sandworm.yml`&quot;">​</a></h2><p>A late-nineties trance anthem in the manner of Sandstorm, with a stuttering sixteenth-note lead of its own. Each build is a scene whose Density rises from 25% to 100%, thinning every clip to its strongest beats and filling it back in.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/sandworm.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/sandworm.yml</code></a> · B minor · 136 BPM · 3:04 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="techno_morph"></a></p><h2 id="morphing-18-techno-morph-yml" tabindex="-1">Morphing: <code>18_techno_morph.yml</code> <a class="header-anchor" href="#morphing-18-techno-morph-yml" aria-label="Permalink to &quot;Morphing: `18_techno_morph.yml`&quot;">​</a></h2><p>A 16-step minimal techno groove whose bass and lead slowly turn into other patterns over 8 or 16 bars, in each morph style. The lead turns into the opening of Für Elise.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/18_techno_morph.yml" target="_blank" rel="noreferrer"><code>examples/learning/18_techno_morph.yml</code></a> · A minor · 126 BPM · 2:17 · 8 scenes · 4 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">morphs</th><th style="text-align:center;">CCs</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="the_mineral"></a></p><h2 id="big-beat-the-mineral-yml" tabindex="-1">Big Beat: <code>the_mineral.yml</code> <a class="header-anchor" href="#big-beat-the-mineral-yml" aria-label="Permalink to &quot;Big Beat: `the_mineral.yml`&quot;">​</a></h2><p>A late-nineties big beat track in the manner of the Crystal Method&#39;s album Vegas, with riffs of its own: a funky breakbeat, a gritty synth bass slurred between some notes by a Glide generator, chord stabs, a screaming saw riff and a build made by a scene&#39;s Density.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/electronic/the_mineral.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/electronic/the_mineral.yml</code></a> · E minor · 128 BPM · 3:00 · 8 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th><th style="text-align:center;">progressions</th><th style="text-align:center;">feel</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="tie"></a></p><h2 id="ties-08-tie-yml" tabindex="-1">Ties: <code>08_tie.yml</code> <a class="header-anchor" href="#ties-08-tie-yml" aria-label="Permalink to &quot;Ties: `08_tie.yml`&quot;">​</a></h2><p>An original downtempo piece in D Mixolydian whose pad draws its chords with the Tie row rather than with gates, so a chord lasts as long as the ties that follow it, and whose ending holds a bass note with ties alone, longer than any gate could make it. The demo also brings in the tracks one at a time, morphs a tune into its answer, grabs an echo and slides a filter, so it&#39;s the closest thing here to a finished song.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/08_tie.yml" target="_blank" rel="noreferrer"><code>examples/learning/08_tie.yml</code></a> · D mixolydian · 84 BPM · 2:59 · 9 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">grabs</th><th style="text-align:center;">morphs</th><th style="text-align:center;">directions</th><th style="text-align:center;">ties</th><th style="text-align:center;">probability</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">CCs</th><th style="text-align:center;">registers</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',79)])])}const g=t(l,[["render",i]]);export{y as __pageData,g as default};
